#!/usr/bin/env bash
# BOLUM_ICGORU deploy — kokpit2 onizlemesine: her kirilim bolumune AI icgoru + odak trend.
#   Sunucuda zaten var: tahsilat-ozet endpoint + /api/bi/kokpit2 route. CANLI /api/bi/kokpit'e DOKUNMAZ.
set -e
cd /opt/krb-assessment
SRV=server_container.mjs
[ -f "$SRV" ] || { echo "HATA: $SRV yok"; exit 1; }
TS=$(date +%s)
cp "$SRV" "$SRV.bak.$TS"; echo "yedek: $SRV.bak.$TS"
printf '%s' '' | base64 -d > /tmp/patch_bolum_icgoru.py
python3 /tmp/patch_bolum_icgoru.py "$SRV"
if ! node --check "$SRV"; then
  echo "!! node --check BASARISIZ — geri aliniyor"; cp "$SRV.bak.$TS" "$SRV"; exit 1
fi
echo "node --check: OK"
printf '%s' '' | base64 -d > shells/kokpit2.html
echo "shells/kokpit2.html satir: $(wc -l < shells/kokpit2.html)"
docker build -t krb-assessment:secure .
docker compose up -d --force-recreate krb-assessment
sleep 4
echo "== route (server.mjs container icinde, 1 bekleniyor) =="
docker exec krb-assessment sh -c "grep -c 'bolum-icgoru' /app/server.mjs" || true
echo ""
echo "== ONIZLE: /api/bi/kokpit2 -> Kirilimlar bolumunde her kartta sparkline + AI satiri."
echo "   (Ilk acilista AI satiri birkac saniye sonra belirir; gunluk cache'lenir.) =="
echo "== DONE =="
